#!/usr/bin/env python3
"""Build/run owned Rust decoder only; preserve frozen static expectation rows."""
from pathlib import Path
import hashlib,json,os,shutil,subprocess,sys
P=Path(__file__).resolve().parent;R=P.parents[2];sys.path.insert(0,str(P));import verify as native;import oracle

def sha(d):return hashlib.sha256(d).hexdigest()
def main():
 out=Path(sys.argv[1]);native.need(not out.exists(),'fresh output directory');out.mkdir(parents=True)
 raw,meta=oracle.freeze();frozen=json.loads((P/'freeze.json').read_text());native.need(raw==(P/'cases.tsv').read_bytes() and sha(raw)==frozen['fixture_sha256'],'pre-Rust corpus drift');native.need(frozen['new_rust_exists'] is False,'historical freeze did not precede Rust');native.need(meta['oracle_sha256']==frozen['oracle_sha256'] and meta['scope_sha256']==frozen['scope_sha256'],'frozen generator/scope drift')
 rows=[line.split('\t') for line in raw.decode().splitlines()];payload=''.join('\t'.join(x[:4])+'\n' for x in rows);expected=''.join(x[4]+'\n' for x in rows)
 component=R/'src/node115-gossip-address-vector';lib=(component/'src/lib.rs').read_text();probe=(component/'src/probe.rs').read_text();manifest=(component/'Cargo.toml').read_text();dependency=(R/'src/node115-u64-reader-state').as_posix();manifest=manifest.replace('path = "../node115-u64-reader-state"','path = '+json.dumps(dependency));cargo=['cargo','+1.95.0'];results=[]
 def run(label,source,release):
  d=out/label;(d/'src').mkdir(parents=True);(d/'Cargo.toml').write_text(manifest);(d/'Cargo.lock').write_bytes((component/'Cargo.lock').read_bytes());(d/'src/lib.rs').write_text(source);(d/'src/probe.rs').write_text(probe);cmd=[*cargo,'build','--offline','--locked','--manifest-path',str(d/'Cargo.toml'),'--bin','address-vector-probe'];cmd += ['--release'] if release else []
  p=subprocess.run(cmd,text=True,capture_output=True);(d/'compiler.stdout').write_text(p.stdout);(d/'compiler.stderr').write_text(p.stderr);native.need(p.returncode==0,'actual compilation failure '+label);exe=d/'target'/('release' if release else 'debug')/'address-vector-probe';p=subprocess.run([str(exe)],input=payload,text=True,capture_output=True);(d/'actual.txt').write_text(p.stdout);(d/'stderr.txt').write_text(p.stderr);native.need(p.returncode==0,'owned probe failed '+label);native.need(len(p.stdout.splitlines())==len(rows),'row count '+label);return p.stdout,{'profile':'release' if release else 'debug','executable_sha256':sha(exe.read_bytes()),'command':cmd}
 for release in [False,True]:
  actual,build=run('production-'+str(release).lower(),lib,release);native.need(actual==expected,'production differs from frozen static expectations');results.append({'matched_rows':len(rows),'output_sha256':sha(actual.encode()),**build})
 controls=[('tag charge8','charged.checked_add(4)','charged.checked_add(8)'),('omit tag count store','*charged = next;\n        if next > limit {\n            return Err(ReadError::Limit);','// no tag charge commit\n        if next > limit {\n            return Err(ReadError::Limit);'),('vector stride16','n.checked_mul(24)','n.checked_mul(16)'),('refund16','charged.checked_sub(24)','charged.checked_sub(16)'),('fixed endian','u32::from_le_bytes(input[..4]','u32::from_be_bytes(input[..4]'),('wrong bool domain','if flag > 1','if flag > 2'),('wrong field5 errors','expected_raw: 5','expected_raw: 3'),('wrong vector bound','for _ in 0..n','for _ in 0..n.saturating_sub(1)')];mutants=[]
 for n,(name,old,new) in enumerate(controls):
  native.need(lib.count(old)==1,'unique mutation selector '+name);actual,build=run('mutant'+str(n),lib.replace(old,new),True);got=actual.splitlines();wanted=expected.splitlines();diff=[i for i,(a,b) in enumerate(zip(got,wanted)) if a!=b];native.need(diff,'surviving compiled mutant '+name);i=min(diff,key=lambda j:len(rows[j][3]));mutants.append({'name':name,'mismatches':len(diff),'witness':rows[i][:4],'expected':wanted[i],'actual':got[i],**build})
 source_paths=[component/'src/lib.rs',component/'src/probe.rs',R/'src/node115-u64-reader-state/lib.rs',R/'src/node115-u64-reader-state/Cargo.toml']
 result={'cases':len(rows),'frozen_fixture_sha256':frozen['fixture_sha256'],'pre_rust_freeze':frozen,'production':results,'compiled_mutants_detected':mutants,'sources':{str(p.relative_to(R)):sha(p.read_bytes()) for p in source_paths},'rustc':subprocess.check_output(['rustc','+1.95.0','-Vv'],text=True),'cargo':subprocess.check_output([*cargo,'--version'],text=True).strip(),'captured_execution_or_emulation':False,'limits':'Whole selected count/vector/element logical relation with real Rust allocation; native allocator failure, ABI, arbitrary modes and complete response are not claimed.'};(out/'qualification.json').write_text(native.dump(result));print(native.dump({'cases':len(rows),'matching_profiles':len(results),'compiled_mutants_detected':len(mutants)}))
if __name__=='__main__':main()
